/**
 * Guards on the checked-in declarative D1 schema (`src/schema/auth-schema.ts`).
 *
 * Two classes of regression are covered:
 *
 *  1. Drift between the schema artifact and the plugin set configured in
 *     `src/auth.ts`. The artifact is regenerated by hand, so nothing else forces
 *     the two to agree.
 *  2. Reintroduction of the `{ mode: "json" }` double-encoding trap on the four
 *     columns whose plugins already JSON-encode them application-side.
 */
import assert from "node:assert/strict";
import test from "node:test";

import { getTableColumns, is, Table } from "drizzle-orm";
import {
  integer,
  sqliteTable,
  text,
  type SQLiteColumn,
} from "drizzle-orm/sqlite-core";

import { createAuthOptions, type AuthRuntime } from "../src/auth.js";
import * as authSchema from "../src/schema/auth-schema.js";
import { assertAuthSchemaMatches, schema } from "../src/schema/check.js";

/**
 * Schema comparison only reads plugin table declarations off the options object,
 * so no database, mailer, or network is ever touched.
 */
const schemaOnlyRuntime: AuthRuntime = {
  baseURL: "https://auth.invalid",
  secret: "schema-test-only",
  resource: "https://api.invalid",
  database: {} as AuthRuntime["database"],
  secondaryStorage: new Proxy({} as AuthRuntime["secondaryStorage"], {
    get() {
      throw new Error("schema tests must not touch secondary storage");
    },
  }),
  sessionTenant: () => {
    throw new Error("schema tests must not touch the database");
  },
  membershipsForUser: () => {
    throw new Error("schema tests must not touch the database");
  },
  fetchClientMetadataResource: () => {
    throw new Error("schema tests must not reach the network");
  },
  emailFrom: "schema@invalid",
  sendEmail: () => {
    throw new Error("schema tests must not send email");
  },
};

const options = createAuthOptions(schemaOnlyRuntime);

/** Every table exported by the schema artifact, keyed by export name. */
const tables = Object.fromEntries(
  Object.entries(authSchema).filter(([, value]) => is(value, Table))
);

/**
 * The 21 tables the configured plugin set writes to. emailOTP reuses core
 * `verification` and cimd adds nothing, so neither appears here.
 */
const EXPECTED_TABLES = [
  // core
  "user",
  "session",
  "account",
  "verification",
  // organization()
  "organization",
  "member",
  "invitation",
  // jwt()
  "jwks",
  // passkey()
  "passkey",
  // agentAuth()
  "agentHost",
  "agent",
  "agentCapabilityGrant",
  "approvalRequest",
  // mcp() via @better-auth/oauth-provider
  "oauthClient",
  "oauthResource",
  "oauthClientResource",
  "oauthRefreshToken",
  "oauthAccessToken",
  "oauthConsent",
  "oauthClientAssertion",
  // oauthDeviceAuthorization()
  "deviceCode",
] as const;

void test("exports exactly the 21 tables the configured plugins need", () => {
  assert.deepEqual(Object.keys(tables).sort(), [...EXPECTED_TABLES].sort());
  assert.equal(Object.keys(tables).length, 21);
});

void test("checked-in schema matches what the configured plugins expect", async () => {
  await assertAuthSchemaMatches(options);
});

void test("startup check rejects a schema that is missing a table", async () => {
  // Drop `agentHost` exactly as a botched regeneration would, and prove the
  // guard turns that into a thrown error rather than a silent runtime failure.
  const { agentHost: _removed, ...withoutAgentHost } = schema;

  await assert.rejects(
    () => assertAuthSchemaMatches(options, {}, withoutAgentHost),
    (error: Error) => {
      assert.match(error.message, /mismatch/i);
      assert.match(error.message, /agentHost/);
      return true;
    },
    "removing agentHost must fail the schema check"
  );

  // The unmodified schema still passes, so the failure above was the removal
  // and not a check left in a poisoned state.
  await assertAuthSchemaMatches(options);
});

void test("startup check rejects a schema that is missing a column", async () => {
  // `agent.metadata` is one of the transform-JSON columns; losing it is the kind
  // of change a careless hand-edit of the artifact would make. Rebuild the table
  // for real, minus that one column, rather than mutating the live definition.
  const agentWithoutMetadata = sqliteTable("agent", {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    userId: text("userId"),
    hostId: text("hostId").notNull(),
    status: text("status").default("active").notNull(),
    mode: text("mode").default("delegated").notNull(),
    publicKey: text("publicKey").notNull(),
    kid: text("kid"),
    jwksUrl: text("jwksUrl"),
    lastUsedAt: integer("lastUsedAt", { mode: "timestamp_ms" }),
    activatedAt: integer("activatedAt", { mode: "timestamp_ms" }),
    expiresAt: integer("expiresAt", { mode: "timestamp_ms" }),
    // metadata deliberately omitted
    createdAt: integer("createdAt", { mode: "timestamp_ms" }).notNull(),
    updatedAt: integer("updatedAt", { mode: "timestamp_ms" }).notNull(),
  });

  await assert.rejects(
    () =>
      assertAuthSchemaMatches(
        options,
        {},
        { ...schema, agent: agentWithoutMetadata }
      ),
    (error: Error) => {
      assert.match(error.message, /mismatch/i);
      assert.match(error.message, /metadata/);
      return true;
    },
    "removing agent.metadata must fail the schema check"
  );

  await assertAuthSchemaMatches(options);
});

/**
 * Columns their plugins declare as plain strings, with `transform.input` /
 * `transform.output` doing the JSON encoding application-side.
 *
 * Marking any of these `{ mode: "json" }` makes Drizzle serialize an
 * already-serialized value. The double-encoded string round-trips as a JSON
 * string rather than an object and capability grants fail SILENTLY — no error,
 * just an agent denied every capability. A regeneration that "helpfully"
 * upgrades these to json mode is the most likely way this breaks.
 */
const PLAIN_TEXT_TRANSFORM_COLUMNS = [
  ["agentHost", "defaultCapabilities"],
  ["agent", "metadata"],
  ["agentCapabilityGrant", "constraints"],
  ["organization", "metadata"],
] as const;

for (const [tableName, columnName] of PLAIN_TEXT_TRANSFORM_COLUMNS) {
  void test(`${tableName}.${columnName} is plain text, never json mode`, () => {
    const table = tables[tableName];
    assert.ok(table, `${tableName} is missing from the schema`);

    const column = getTableColumns(table as Table)[columnName] as
      | SQLiteColumn
      | undefined;
    assert.ok(column, `${tableName}.${columnName} is missing from the schema`);

    // Drizzle reports `SQLiteTextJson` for `text(..., { mode: "json" })` and
    // plain `SQLiteText` otherwise. This is the discriminator that matters:
    // `config.mode` is undefined in BOTH cases and cannot be asserted on.
    assert.equal(
      column.columnType,
      "SQLiteText",
      `${tableName}.${columnName} must be plain text, not { mode: "json" } — the plugin ` +
        "already JSON-encodes it, so json mode double-encodes and silently breaks it"
    );

    // Behavioural proof of the same thing: the driver value must pass through
    // untouched. A json-mode column would return '"{\\"a\\":1}"' here.
    const encoded = JSON.stringify({ a: 1 });
    assert.equal(
      column.mapToDriverValue(encoded),
      encoded,
      `${tableName}.${columnName} must not re-serialize an already-encoded value`
    );
  });
}
